contract InvMutTest {
    C c;
    constructor() { c = new C(address(this)); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}
    function run(address _recipient) public payable {
        require(c.owner() == address(this));
        require(_recipient == address(this));
        c.withdrawAll(_recipient); if (__ESBMC_reverted()) return;
        assert(address(c).balance == 0);
    }
    receive() external payable {}
    fallback() external payable {}
}

