pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {Phishable} from "../src/Phishable.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    Phishable c;

    function setUp() public {
        c = new Phishable(address(this));
    }

    function _run(address _recipient) internal {
        vm.assume(c.owner() == address(this));
        _recipient = address(this);
        try c.withdrawAll(_recipient) {} catch { return; }
        assertTrue(address(c).balance == 0);
    }

    function testFuzz_run(address _recipient) public {
        _run(_recipient);
    }

    receive() external payable {}

    fallback() external payable {}
}
